<?php
require dirname(__DIR__).'/app/bootstrap.php';require_admin();
$tab=$_GET['tab']??'dashboard';
if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();$action=$_POST['action']??'';
    if($action==='save_product'){
        $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'')?:slugify($name);$data=[(int)$_POST['category_id'],($_POST['brand_id']??'')!==''?(int)$_POST['brand_id']:null,$name,$slug,trim($_POST['sku']??''),trim($_POST['barcode']??''),(float)$_POST['purchase_price'],(float)$_POST['sale_price'],($_POST['compare_price']??'')!==''?(float)$_POST['compare_price']:null,(int)$_POST['vat_rate'],(int)$_POST['stock'],(int)$_POST['critical_stock'],$_POST['shipping_policy']??'standard',!empty($_POST['same_day_delivery'])?1:0,trim($_POST['description']??''),!empty($_POST['is_active'])?1:0,!empty($_POST['is_featured'])?1:0];
        if($id){$s=db()->prepare('UPDATE products SET category_id=?,brand_id=?,name=?,slug=?,sku=?,barcode=?,purchase_price=?,sale_price=?,compare_price=?,vat_rate=?,stock=?,critical_stock=?,shipping_policy=?,same_day_delivery=?,description=?,is_active=?,is_featured=?,updated_at=NOW() WHERE id=?');$data[]=$id;$s->execute($data);admin_log('product_update','#'.$id.' '.$name);}else{$s=db()->prepare('INSERT INTO products(category_id,brand_id,name,slug,sku,barcode,purchase_price,sale_price,compare_price,vat_rate,stock,critical_stock,shipping_policy,same_day_delivery,description,is_active,is_featured,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute($data);admin_log('product_create',$name);}flash('success','Ürün kaydedildi.');redirect('webyonet/?tab=products');
    }
    if($action==='save_category'){$name=trim($_POST['name']??'');if($name){$slug=slugify($name);$parent=($_POST['parent_id']??'')!==''?(int)$_POST['parent_id']:null;$base=$slug;if($parent){$q=db()->prepare('SELECT slug FROM categories WHERE id=?');$q->execute([$parent]);if($ps=$q->fetchColumn())$slug=$ps.'-'.$base;}db()->prepare('INSERT INTO categories(parent_id,name,slug,sort_order,is_active) VALUES(?,?,?,?,1)')->execute([$parent,$name,$slug,(int)($_POST['sort_order']??0)]);admin_log('category_create',$name);}flash('success','Kategori eklendi.');redirect('webyonet/?tab=categories');}
    if($action==='save_brand'){$name=trim($_POST['name']??'');if($name){db()->prepare('INSERT INTO brands(name,slug,is_active,created_at) VALUES(?,?,1,NOW())')->execute([$name,slugify($name)]);admin_log('brand_create',$name);}flash('success','Marka eklendi.');redirect('webyonet/?tab=brands');}
    if($action==='save_shipping'){db()->prepare('INSERT INTO shipping_companies(name,price,is_active) VALUES(?,?,1)')->execute([trim($_POST['name']??''),(float)($_POST['price']??0)]);admin_log('shipping_create',trim($_POST['name']??''));flash('success','Kargo firması eklendi.');redirect('webyonet/?tab=shipping');}
    if($action==='save_settings'){foreach(['free_shipping_limit','same_day_enabled','same_day_cutoff','same_day_free_limit','same_day_under_limit_fee','same_day_daily_capacity'] as $k){$v=$_POST[$k]??'';db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,$v]);}admin_log('settings_update');flash('success','Ayarlar güncellendi.');redirect('webyonet/?tab=settings');}
    if($action==='order_status'){$id=(int)$_POST['id'];$status=$_POST['status']??'new';if(in_array($status,['new','approved','preparing','shipped','delivered','cancelled'],true)){db()->prepare('UPDATE orders SET status=?,updated_at=NOW() WHERE id=?')->execute([$status,$id]);admin_log('order_status','#'.$id.' '.$status);}redirect('webyonet/?tab=orders');}
}
$stats=['revenue'=>(float)db()->query("SELECT COALESCE(SUM(grand_total),0) FROM orders WHERE DATE(created_at)=CURDATE() AND status<>'cancelled'")->fetchColumn(),'orders'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE DATE(created_at)=CURDATE()")->fetchColumn(),'products'=>(int)db()->query('SELECT COUNT(*) FROM products WHERE is_active=1')->fetchColumn(),'low'=>(int)db()->query('SELECT COUNT(*) FROM products WHERE is_active=1 AND stock<=critical_stock')->fetchColumn(),'carts'=>(int)db()->query("SELECT COUNT(*) FROM carts WHERE converted_order_id IS NULL AND subtotal>0 AND updated_at<DATE_SUB(NOW(),INTERVAL 30 MINUTE)")->fetchColumn()];
$cats=db()->query('SELECT c.*,p.name parent_name FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY COALESCE(c.parent_id,0),c.sort_order,c.name')->fetchAll();$brands=db()->query('SELECT * FROM brands ORDER BY name')->fetchAll();$products=db()->query('SELECT p.*,c.name category_name,b.name brand_name FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN brands b ON b.id=p.brand_id ORDER BY p.id DESC LIMIT 200')->fetchAll();$orders=db()->query('SELECT * FROM orders ORDER BY id DESC LIMIT 100')->fetchAll();$shipping=db()->query('SELECT * FROM shipping_companies ORDER BY id')->fetchAll();$searches=db()->query('SELECT search_term,COUNT(*) total FROM search_logs WHERE created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) GROUP BY search_term ORDER BY total DESC LIMIT 10')->fetchAll();$zero=db()->query('SELECT search_term,COUNT(*) total FROM search_logs WHERE result_count=0 GROUP BY search_term ORDER BY total DESC LIMIT 10')->fetchAll();
$edit=null;if($tab==='product_edit'&&!empty($_GET['id'])){$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['id']]);$edit=$s->fetch();}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TOPLUCA WebYönet</title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial;background:#f4f5f7;color:#171717}a{text-decoration:none;color:inherit}.layout{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{background:#171717;color:#ddd;padding:18px 12px}.logo{font-size:25px;font-weight:900;color:#fff;padding:8px}.logo span{color:#ff5a00}.side a{display:block;padding:10px 12px;border-radius:8px;margin:2px 0;font-size:13px}.side a:hover{background:#2a2a2a}.top{height:66px;background:#fff;border-bottom:1px solid #eee;padding:0 24px;display:flex;justify-content:space-between;align-items:center}.main{padding:24px}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:12px}.card,.panel{background:#fff;border:1px solid #e5e5e5;border-radius:12px}.card{padding:17px}.card small{color:#777}.card strong{display:block;font-size:22px;margin-top:5px}.panel{margin-top:18px;overflow:hidden}.ph{padding:15px 17px;border-bottom:1px solid #eee;display:flex;justify-content:space-between}.pb{padding:17px}.btn{display:inline-block;border:0;background:#ff5a00;color:#fff;padding:9px 12px;border-radius:7px;font-weight:800;cursor:pointer}.btn.gray{background:#e9e9e9;color:#222}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #eee;text-align:left;font-size:12px}th{background:#fafafa;color:#777}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}label{font-size:11px;font-weight:800}input,select,textarea{width:100%;padding:9px;border:1px solid #ddd;border-radius:7px;margin-top:5px}.full{grid-column:1/-1}.flash{padding:11px;border-radius:8px;margin-bottom:10px}.success{background:#eaf8ef;color:#176b36}.error{background:#fff0f0;color:#a22}@media(max-width:900px){.layout{display:block}.side{position:static}.cards{grid-template-columns:1fr 1fr}.grid{grid-template-columns:1fr}.full{grid-column:auto}.main{padding:14px}.table{overflow:auto}}</style></head><body><div class="layout"><aside class="side"><div class="logo">TOPLU<span>CA</span></div><a href="?tab=dashboard">▣ Dashboard</a><a href="?tab=orders">Siparişler</a><a href="?tab=products">Ürünler</a><a href="?tab=categories">Kategoriler</a><a href="?tab=brands">Markalar</a><a href="?tab=shipping">Kargo Yönetimi</a><a href="?tab=analytics">Arama & İstatistik</a><a href="?tab=settings">Site Ayarları</a></aside><div><header class="top"><strong>TOPLUCA Yönetim Merkezi</strong><div><a target="_blank" href="<?=url()?>">Siteyi Gör</a> · <a href="<?=url('webyonet/logout.php')?>">Çıkış</a></div></header><div class="main"><?php foreach(flashes() as $f):?><div class="flash <?=h($f['type'])?>"><?=h($f['message'])?></div><?php endforeach;?>
<?php if($tab==='dashboard'):?><div class="cards"><div class="card"><small>BUGÜNKÜ CİRO</small><strong><?=money($stats['revenue'])?></strong></div><div class="card"><small>BUGÜNKÜ SİPARİŞ</small><strong><?=$stats['orders']?></strong></div><div class="card"><small>AKTİF ÜRÜN</small><strong><?=$stats['products']?></strong></div><div class="card"><small>KRİTİK STOK</small><strong><?=$stats['low']?></strong></div><div class="card"><small>TERK SEPET</small><strong><?=$stats['carts']?></strong></div></div><section class="panel"><div class="ph"><strong>Hızlı İşlemler</strong></div><div class="pb"><a class="btn" href="?tab=product_edit">+ Ürün Ekle</a> <a class="btn gray" href="?tab=categories">+ Kategori</a></div></section>
<?php elseif($tab==='products'):?><section class="panel"><div class="ph"><strong>Ürün Yönetimi</strong><a class="btn" href="?tab=product_edit">+ Yeni Ürün</a></div><div class="table"><table><tr><th>Ürün</th><th>Kategori</th><th>Marka</th><th>Alış</th><th>Satış</th><th>Stok</th><th></th></tr><?php foreach($products as $p):?><tr><td><b><?=h($p['name'])?></b><br><?=h($p['sku'])?></td><td><?=h($p['category_name'])?></td><td><?=h($p['brand_name'])?></td><td><?=money($p['purchase_price'])?></td><td><?=money($p['sale_price'])?></td><td><?=(int)$p['stock']?></td><td><a class="btn gray" href="?tab=product_edit&id=<?=(int)$p['id']?>">Düzenle</a></td></tr><?php endforeach;?></table></div></section>
<?php elseif($tab==='product_edit'):?><?php $p=$edit?:['id'=>'','category_id'=>'','brand_id'=>'','name'=>'','slug'=>'','sku'=>'','barcode'=>'','purchase_price'=>'','sale_price'=>'','compare_price'=>'','vat_rate'=>20,'stock'=>0,'critical_stock'=>5,'shipping_policy'=>'standard','same_day_delivery'=>1,'description'=>'','is_active'=>1,'is_featured'=>0];?><section class="panel"><div class="ph"><strong><?=$edit?'Ürün Düzenle':'Yeni Ürün'?></strong></div><div class="pb"><form method="post" class="grid"><?=csrf_field()?><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=h((string)$p['id'])?>"><label class="full">Ürün Adı<input name="name" required value="<?=h($p['name'])?>"></label><label>Kategori<select name="category_id" required><option value="">Seçin</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>" <?=(int)$p['category_id']===(int)$c['id']?'selected':''?>><?=h(($c['parent_name']?$c['parent_name'].' → ':'').$c['name'])?></option><?php endforeach;?></select></label><label>Marka<select name="brand_id"><option value="">Markasız</option><?php foreach($brands as $b):?><option value="<?=(int)$b['id']?>" <?=(int)$p['brand_id']===(int)$b['id']?'selected':''?>><?=h($b['name'])?></option><?php endforeach;?></select></label><label>SEO URL<input name="slug" value="<?=h($p['slug'])?>"></label><label>SKU<input name="sku" required value="<?=h($p['sku'])?>"></label><label>Barkod / ISBN<input name="barcode" value="<?=h($p['barcode'])?>"></label><label>KDV %<input type="number" name="vat_rate" value="<?=(int)$p['vat_rate']?>"></label><label>Alış Fiyatı<input type="number" step="0.01" name="purchase_price" value="<?=h((string)$p['purchase_price'])?>"></label><label>Satış Fiyatı<input type="number" step="0.01" name="sale_price" required value="<?=h((string)$p['sale_price'])?>"></label><label>Eski Fiyat<input type="number" step="0.01" name="compare_price" value="<?=h((string)$p['compare_price'])?>"></label><label>Stok<input type="number" name="stock" value="<?=(int)$p['stock']?>"></label><label>Kritik Stok<input type="number" name="critical_stock" value="<?=(int)$p['critical_stock']?>"></label><label>Kargo<select name="shipping_policy"><option value="standard" <?=$p['shipping_policy']==='standard'?'selected':''?>>Standart</option><option value="free" <?=$p['shipping_policy']==='free'?'selected':''?>>Ücretsiz</option><option value="special" <?=$p['shipping_policy']==='special'?'selected':''?>>Özel</option></select></label><label><input style="width:auto" type="checkbox" name="same_day_delivery" value="1" <?=(int)$p['same_day_delivery']?'checked':''?>> Ankara aynı gün</label><label><input style="width:auto" type="checkbox" name="is_featured" value="1" <?=(int)$p['is_featured']?'checked':''?>> Öne çıkar</label><label><input style="width:auto" type="checkbox" name="is_active" value="1" <?=(int)$p['is_active']?'checked':''?>> Aktif</label><label class="full">Açıklama<textarea name="description"><?=h($p['description'])?></textarea></label><div class="full"><button class="btn">Kaydet</button></div></form></div></section>
<?php elseif($tab==='categories'):?><div class="grid"><section class="panel"><div class="ph"><strong>Yeni Kategori</strong></div><div class="pb"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_category"><label>Ad<input name="name" required></label><label>Üst Kategori<select name="parent_id"><option value="">Ana Kategori</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>"><?=h($c['name'])?></option><?php endforeach;?></select></label><label>Sıra<input type="number" name="sort_order" value="0"></label><br><button class="btn">Ekle</button></form></div></section><section class="panel"><div class="ph"><strong>Kategoriler</strong></div><div class="table"><table><?php foreach($cats as $c):?><tr><td><?=h($c['name'])?></td><td><?=h($c['parent_name']??'Ana Kategori')?></td></tr><?php endforeach;?></table></div></section></div>
<?php elseif($tab==='brands'):?><div class="grid"><section class="panel"><div class="ph"><strong>Yeni Marka</strong></div><div class="pb"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_brand"><label>Marka Adı<input name="name" required></label><br><button class="btn">Ekle</button></form></div></section><section class="panel"><div class="ph"><strong>Markalar</strong></div><div class="pb"><?php foreach($brands as $b):?><p><?=h($b['name'])?></p><?php endforeach;?></div></section></div>
