<?php elseif($tab==='orders'):?><section class="panel"><div class="ph"><strong>Siparişler</strong></div><div class="table"><table><tr><th>No</th><th>Müşteri</th><th>Şehir</th><th>Tutar</th><th>Durum</th></tr><?php foreach($orders as $o):?><tr><td><?=h($o['order_no'])?></td><td><?=h($o['customer_name'])?><br><?=h($o['customer_email'])?></td><td><?=h($o['city'])?></td><td><?=money($o['grand_total'])?></td><td><form method="post" style="display:flex;gap:5px"><?=csrf_field()?><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><select name="status"><?php foreach(['new'=>'Yeni','approved'=>'Onay','preparing'=>'Hazırlanıyor','shipped'=>'Kargo/Dağıtım','delivered'=>'Teslim','cancelled'=>'İptal'] as $k=>$v):?><option value="<?=$k?>" <?=$o['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn gray">Kaydet</button></form></td></tr><?php endforeach;?></table></div></section>
